#!/usr/bin/env python3
"""Build the standalone updater from the canonical deployment sources."""
import pathlib
import sys
root=pathlib.Path(__file__).resolve().parents[1]
header='''#!/bin/sh
# Generated by tools/build_update.py. Edit deploy/app.py, not this embedded copy.
set -eu
[ "$(id -u)" -eq 0 ] || { echo 'Uruchom jako root'; exit 1; }
command -v apk >/dev/null 2>&1 || { echo 'Wymaga Alpine Linux'; exit 1; }
STAGE=$(mktemp -d)
trap 'rm -rf "$STAGE"' EXIT HUP INT TERM
'''
result=header
for name,delimiter in [('app.py','PY'),('config.example.json','CONFIG'),('deploy.sh','DEPLOY'),('frog-soc.logrotate','ROTATION')]:
    result+='cat > "$STAGE/'+name+'" <<\''+delimiter+"'\n"+(root/'deploy'/name).read_text().rstrip()+'\n'+delimiter+'\n'
result+='sh "$STAGE/deploy.sh"\n'
target=root/'update-frog-soc-4.sh'
if '--check' in sys.argv:
    if target.read_text()!=result:
        raise SystemExit('Updater wymaga regeneracji: python3 tools/build_update.py')
else:
    target.write_text(result)
